'use strict';
let currentUser=null,cloudRevision=0,dirty=false,syncing=false,syncConflict=false,syncTimer;
const legacyData=localStorage.getItem('zen-kanban-v1');
async function requestAPI(path,method='GET',body){const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const result=await r.json();if(!r.ok)throw Object.assign(new Error(result.error||'Yêu cầu không thành công'),{status:r.status});return result;}
function authScreen(mode='login',message=''){document.body.classList.add('signed-out');document.querySelector('#auth-screen')?.remove();const screen=document.createElement('section');screen.id='auth-screen';const reset=mode==='reset',register=mode==='register',forgot=mode==='forgot',verify=mode==='verify';screen.innerHTML=`<div class="auth-story"><a class="auth-logo" href="/">kanban <span>ZEN STUDIO</span></a><span class="eyebrow">KHÔNG GIAN LÀM VIỆC CÁ NHÂN</span><h1>Gọn công việc.<br>Rộng tâm trí.</h1><p>Từ ý tưởng đầu tiên đến công việc hoàn thành.<br>Mọi dự án của bạn, luôn ở cùng một nơi.</p><div class="auth-mini"><span>Idea</span><span>List</span><span>Doing</span><span>Done ✓</span></div><small>Một sản phẩm thuộc Hương Thiền Nature</small></div><div class="auth-card"><span class="eyebrow">CHÀO MỪNG BẠN</span><h2>${register?'Tạo tài khoản':forgot?'Quên mật khẩu':reset?'Mật khẩu mới':verify?'Xác minh email':'Trở lại không gian của bạn'}</h2><p id="auth-message" role="status">${esc(message)}</p><form id="auth-form">${!reset&&!verify?field('Email','email','','email',true,254):''}${!forgot&&!verify?field('Mật khẩu','password','','password',true,128):''}${!forgot&&!verify?'<p class="subtext">Mật khẩu từ 10 ký tự. Không dùng lại mật khẩu ở nơi khác.</p><label class="auth-show"><input type="checkbox" id="show-password"> Hiện mật khẩu</label>':''}<button class="btn primary" type="submit">${register?'Tạo tài khoản':forgot?'Gửi liên kết khôi phục':reset?'Lưu mật khẩu':verify?'Xác minh email':'Đăng nhập'}</button></form><div class="auth-links"><button data-auth="login">Đăng nhập</button><button data-auth="register">Tạo tài khoản</button><button data-auth="forgot">Quên mật khẩu?</button></div><button id="resend-verify" class="text-btn">Gửi lại email xác minh</button><p class="auth-note">Dữ liệu riêng theo tài khoản · Đồng bộ giữa thiết bị<br>Dữ liệu cũ trên máy vẫn được giữ; có thể nhập sau khi đăng nhập.</p></div>`;document.body.append(screen);screen.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>authScreen(b.dataset.auth));$('#show-password')?.addEventListener('change',e=>screen.querySelector('[name=password]').type=e.target.checked?'text':'password');$('#resend-verify').onclick=async()=>{const email=screen.querySelector('[name=email]')?.value;if(!email)return $('#auth-message').textContent='Nhập email trước khi gửi lại.';try{$('#auth-message').textContent=(await requestAPI('resend','POST',{email})).message;}catch(e){$('#auth-message').textContent=e.message;}};$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));if(reset||verify)values.token=location.hash.split('=')[1];const result=await requestAPI(mode==='register'?'register':mode==='forgot'?'forgot':reset?'reset':verify?'verify':'login','POST',values);if(mode==='login'){await openAccount();}else if(reset||verify){history.replaceState(null,'','/');authScreen('login',result.message);}else $('#auth-message').textContent=result.message;}catch(error){$('#auth-message').textContent=error.message;}finally{button.disabled=false;}};}
function syncStatus(text){$('#save-state').textContent=text;}
function cacheCloud(){localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(KEY+'-sync',JSON.stringify({revision:cloudRevision,dirty}));}
async function openAccount(){const me=await requestAPI('me');currentUser=me.user;KEY='zen-account-'+currentUser.id;const remote=await requestAPI('workspace');cloudRevision=remote.revision;dirty=false;syncConflict=false;const cached=localStorage.getItem(KEY),meta=JSON.parse(localStorage.getItem(KEY+'-sync')||'{}');if(meta.dirty&&cached){const pending=JSON.parse(cached);if(valid(pending)){data=pending;cloudRevision=meta.revision;dirty=true;}}if(!dirty)data=remote.data;cacheCloud();document.body.classList.remove('signed-out');$('#auth-screen')?.remove();view='dashboard';active=null;query='';render();syncStatus(dirty?'● Đang đồng bộ…':'● Đã đồng bộ');document.querySelectorAll('.avatar').forEach(el=>el.textContent=currentUser.email.slice(0,2).toUpperCase());if(dirty)await flushCloud();}
async function flushCloud(){if(!currentUser||!dirty||syncing||syncConflict)return;syncing=true;const snapshot=JSON.stringify(data);try{syncStatus('● Đang đồng bộ…');const result=await requestAPI('workspace','PUT',{data:JSON.parse(snapshot),revision:cloudRevision});cloudRevision=result.revision;dirty=JSON.stringify(data)!==snapshot;cacheCloud();syncStatus(dirty?'● Đang đồng bộ…':'● Đã đồng bộ');}catch(e){if(e.status===409){syncConflict=true;syncStatus('⚠ Cần xử lý xung đột');notify('Có cập nhật trên thiết bị khác. Mở Tài khoản để giữ bản sao và chọn dữ liệu.');}else{syncStatus('⚠ Đã lưu trên máy · Chờ mạng');if(e.status===401)notify('Phiên đăng nhập hết hạn. Dữ liệu chưa gửi vẫn được lưu riêng trên máy.');}}finally{syncing=false;if(dirty&&!syncConflict&&navigator.onLine)syncTimer=setTimeout(flushCloud,10000);}}
save=function(){if(!currentUser)return false;dirty=true;try{cacheCloud();syncStatus('● Đã lưu trên máy · Đang đồng bộ');clearTimeout(syncTimer);syncTimer=setTimeout(flushCloud,600);return true;}catch{notify('Không lưu được trên máy. Hãy xuất JSON để giữ dữ liệu.');return false;}};
async function pollCloud(){if(!currentUser||dirty||syncing||$('#editor').open)return;try{const remote=await requestAPI('workspace');if(remote.revision!==cloudRevision){data=remote.data;cloudRevision=remote.revision;cacheCloud();render();syncStatus('● Đã cập nhật từ thiết bị khác');}}catch{syncStatus('⚠ Chờ kết nối');}}
function accountPanel(){if(!currentUser)return;modal(`<h2>Tài khoản & thông báo</h2><p>${esc(currentUser.email)}</p><p class="help-copy">Đồng bộ tự động khi chỉnh sửa. Thiết bị khác nhận cập nhật sau khoảng 10 giây khi đang mở; kết nối lại sẽ gửi dữ liệu chờ.</p><label class="check-row"><input id="email-reminder" type="checkbox" ${currentUser.email_reminders?'checked':''}><span>Email nhắc việc mỗi ngày lúc 08:00 (Việt Nam), khi có việc đến hạn/quá hạn.</span></label><div class="help-actions"><button class="btn" type="button" id="enable-push">Bật thông báo trình duyệt</button><button class="btn" type="button" id="disable-push">Tắt thông báo thiết bị này</button><button class="btn" type="button" id="sync-now">Đồng bộ ngay</button>${legacyData?'<button class="btn" type="button" id="import-legacy">Nhập dữ liệu cũ trên máy</button>':''}<button class="btn" type="button" data-action="export">Xuất bản sao JSON</button>${syncConflict?'<button class="btn danger" type="button" id="resolve-cloud">Dùng bản trên máy chủ</button>':''}<button class="btn danger" type="button" id="sign-out">Đăng xuất</button></div><p class="help-copy" style="margin-top:15px">Thông báo cần được bạn cho phép. Trình duyệt có thể giới hạn thông báo khi bị đóng hoàn toàn. Email nhắc việc có thể tắt bất cứ lúc nào.</p>`,null,true);$('#email-reminder').onchange=async e=>{try{await requestAPI('preferences','PUT',{emailReminders:e.target.checked});currentUser.email_reminders=e.target.checked?1:0;notify('Đã lưu cài đặt email.');}catch(error){e.target.checked=!e.target.checked;notify(error.message);}};$('#enable-push').onclick=enablePush;$('#disable-push').onclick=async()=>{try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await requestAPI('push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe();}notify('Đã tắt thông báo trên thiết bị này.');}catch(e){notify(e.message);}};$('#sync-now').onclick=async()=>{await flushCloud();await pollCloud();notify(syncConflict?'Cần xử lý xung đột dữ liệu.':dirty?'Đang chờ đồng bộ.':'Dữ liệu đã cập nhật.');};$('#import-legacy')?.addEventListener('click',()=>modal('<h2>Nhập dữ liệu cũ?</h2><p>Thao tác thêm dự án cũ vào tài khoản này; không xóa dữ liệu đang có. Nhập nhiều lần sẽ tạo các bản sao.</p>',()=>{try{const old=JSON.parse(legacyData);if(!valid(old))throw Error('Dữ liệu cũ không hợp lệ.');for(const p of old.projects){p.id=uid();for(const t of p.tasks){t.id=uid();t.checks.forEach(c=>c.id=uid());}}if(data.projects.length+old.projects.length>100)throw Error('Vượt giới hạn 100 dự án.');data.projects.push(...old.projects);save();render();$('#editor').close();notify('Đã nhập dữ liệu cũ vào tài khoản.');}catch(e){notify(e.message);}}));$('#resolve-cloud')?.addEventListener('click',()=>modal('<h2>Dùng dữ liệu trên máy chủ?</h2><p>Bản chỉnh sửa hiện tại vẫn được lưu thành bản sao trên máy. Bạn nên xuất JSON trước khi tiếp tục. Thao tác này thay bảng đang hiển thị bằng dữ liệu máy chủ.</p>',async()=>{localStorage.setItem(KEY+'-conflict-'+Date.now(),JSON.stringify(data));dirty=false;syncConflict=false;await pollCloud();const remote=await requestAPI('workspace');data=remote.data;cloudRevision=remote.revision;cacheCloud();$('#editor').close();render();syncStatus('● Đã đồng bộ');}));$('#sign-out').onclick=async()=>{try{await flushCloud();if(dirty){notify('Còn dữ liệu chưa đồng bộ. Hãy xuất JSON hoặc chờ đồng bộ trước khi đăng xuất.');return;}const reg=await navigator.serviceWorker.getRegistration();const sub=await reg?.pushManager.getSubscription();if(sub){await requestAPI('push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe();}await requestAPI('logout','POST',{});currentUser=null;data={schema:1,projects:[]};$('#editor').close();authScreen();}catch(e){notify(e.message);}};}
async function enablePush(){try{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Trình duyệt chưa hỗ trợ Web Push. Hãy dùng email nhắc việc.');if(await Notification.requestPermission()!=='granted')throw Error('Chưa được cấp quyền thông báo.');await navigator.serviceWorker.register('/sw.js');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const {key}=await requestAPI('push-key');const raw=atob(key.replace(/-/g,'+').replace(/_/g,'/'));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))});}await requestAPI('push','POST',{endpoint:sub.endpoint});notify('Đã bật thông báo nhắc việc hằng ngày trên thiết bị này.');}catch(e){notify(e.message);}}
reminderBtn.onclick=()=>accountPanel();document.querySelectorAll('.top-actions>.avatar').forEach(b=>{b.removeAttribute('data-action');b.onclick=accountPanel;});const accountButton=document.createElement('button');accountButton.className='nav';accountButton.innerHTML=svgIcon('tasks')+' Tài khoản & thông báo';accountButton.onclick=accountPanel;nav.append(accountButton);
window.addEventListener('online',()=>flushCloud());document.addEventListener('visibilitychange',()=>{if(!document.hidden){flushCloud();pollCloud();}});setInterval(pollCloud,10000);
const priorStorage=()=>{};
(async()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const mode=location.hash.startsWith('#reset=')?'reset':location.hash.startsWith('#verify=')?'verify':null;if(mode)return authScreen(mode);try{await openAccount();}catch{authScreen();}})();
